async function personalized(){const u=await user();if(!u){location.href="login.html";return}const {data:pf}=await crSupabase.from("podcast_follows").select("podcast_id").eq("user_id",u.id);const ids=(pf||[]).map(x=>x.podcast_id);let followed=[],feed=[];if(ids.length){const [p,e]=await Promise.all([crSupabase.from("podcasts").select("*").in("id",ids).eq("status","published").order("created_at",{ascending:false}),crSupabase.from("podcast_episodes").select("*").in("podcast_id",ids).eq("status","published").order("published_at",{ascending:false}).limit(20)]);followed=p.data||[];feed=e.data||[]}const {data:newest}=await crSupabase.from("podcast_episodes").select("*").eq("status","published").order("published_at",{ascending:false}).limit(8);shell('<section class="section wrap"><span class="eyebrow">YOUR FEED</span><h1>YOUR <span class="glow">PODCASTING UNIVERSE</span></h1><p>New episodes from the shows you follow, plus the latest voices across CrowRules Podcasting.</p><div class="actions"><a class="btn primary" href="member.html">MY HUB</a><a class="btn" href="my-library.html">MY LIBRARY</a></div><h2>Following</h2><div class="grid">'+(followed.map(podcastCard).join("")||"<p>You aren't following any podcasts yet. Explore shows and tap FOLLOW.</p>")+'</div><h2>New From Your Shows</h2><div class="grid">'+(feed.map(episodeCard).join("")||"<p>Follow a podcast to build your personalized feed.</p>")+'</div><h2>Latest Across <span class="glow">CrowRules</span></h2><div class="grid">'+(newest||[]).map(episodeCard).join("")+'</div></section>')}

async function members(){const u=await user();if(!u){location.href="login.html";return}const {data:ps}=await crSupabase.from("podcast_member_profiles").select("*").eq("is_public",true).order("updated_at",{ascending:false}).limit(40);const {data:following}=await crSupabase.from("podcast_member_follows").select("followed_user_id").eq("follower_user_id",u.id);const ids=new Set((following||[]).map(x=>x.followed_user_id));shell('<section class="section wrap"><span class="eyebrow">COMMUNITY</span><h1>THE <span class="glow">CROWRULES NETWORK</span></h1><p>Discover members, creators and voices across CrowRules Podcasting.</p><div class="grid">'+(ps||[]).map(p=>'<div class="card"><div class="eyebrow">'+(ids.has(p.user_id)?"FOLLOWING":"MEMBER")+'</div><h3>'+esc(p.display_name||p.username||"CrowRules Member")+'</h3><p>@'+esc(p.username||"member")+'</p><p>'+esc(p.tagline||p.bio||"")+'</p><div class="actions"><a class="btn" href="member-profile.html?id='+encodeURIComponent(p.user_id)+'">VIEW PROFILE</a>'+(p.user_id!==u.id?'<button class="btn '+(ids.has(p.user_id)?"":"primary")+'" onclick="toggleMemberFollow(\''+p.user_id+'\',this)">'+(ids.has(p.user_id)?"UNFOLLOW":"FOLLOW")+'</button>':"")+'</div></div>').join("")+'</div></section>')}
async function toggleMemberFollow(id,btn){const u=await user();if(!u||u.id===id)return;const {data:row}=await crSupabase.from("podcast_member_follows").select("id").eq("follower_user_id",u.id).eq("followed_user_id",id).maybeSingle();if(row){const r=await crSupabase.from("podcast_member_follows").delete().eq("id",row.id);if(!r.error){btn.textContent="FOLLOW";btn.classList.add("primary")}}else{const r=await crSupabase.from("podcast_member_follows").insert({follower_user_id:u.id,followed_user_id:id});if(!r.error){btn.textContent="UNFOLLOW";btn.classList.remove("primary")}else alert(r.error.message)}}
async function reputation(){const u=await user();if(!u){location.href="login.html";return}const [s,unlocks,prof]=await Promise.all([crSupabase.from("podcast_member_profile_stats").select("*").eq("user_id",u.id).maybeSingle(),crSupabase.from("podcast_profile_achievement_unlocks").select("achievement_key,unlocked_at").eq("user_id",u.id).order("unlocked_at",{ascending:false}),crSupabase.from("podcast_member_profiles").select("display_name,username,badge,featured_achievement").eq("user_id",u.id).maybeSingle()]);const x=s.data||{},points=Number(x.crowpoints||0),ach=(unlocks.data||[]).length;const score=points+ach*100+Number(x.total_plays||0)*2+Number(x.episode_comments||0)*5+Number(x.episode_reactions||0)*2+Number(x.member_followers||0)*5;const level=Math.max(1,Math.floor(score/500)+1),next=level*500,progress=Math.min(100,Math.round((score-(level-1)*500)/500*100));let tier=level>=10?"LEGEND":level>=7?"VETERAN":level>=4?"ESTABLISHED":"RISING";shell('<section class="section wrap"><span class="eyebrow">MEMBER REPUTATION</span><h1><span class="glow">LEVEL '+level+'</span></h1><div class="grid"><div class="card"><small>REPUTATION SCORE</small><h2>'+score.toLocaleString()+'</h2><p>'+tier+' MEMBER</p></div><div class="card"><small>CROWPOINTS</small><h2>'+points.toLocaleString()+'</h2></div><div class="card"><small>ACHIEVEMENTS</small><h2>'+ach+'</h2></div><div class="card"><small>FOLLOWERS</small><h2>'+Number(x.member_followers||0).toLocaleString()+'</h2></div></div><div class="card"><h3>LEVEL PROGRESS</h3><div style="height:12px;background:rgba(255,255,255,.08);border-radius:999px;overflow:hidden"><div style="width:'+progress+'%;height:100%;background:linear-gradient(90deg,#00ffff,#9b5cff,#ff4fd8)"></div></div><p>'+progress+'% toward Level '+(level+1)+'</p></div><div class="actions"><a class="btn primary" href="achievements.html">ACHIEVEMENTS</a><a class="btn" href="crowpoints.html">CROWPOINTS</a><a class="btn" href="member.html">MEMBER HUB</a></div></section>')}

async function memberProfile(){const u=await user();const id=new URLSearchParams(location.search).get("id")||u?.id;if(!id){location.href="login.html";return}const {data:p}=await crSupabase.from("podcast_member_profiles").select("*").eq("user_id",id).eq("is_public",true).maybeSingle();if(!p){shell('<section class="section wrap"><div class="form"><h2>PROFILE NOT FOUND</h2></div></section>');return}const {data:s}=await crSupabase.from("podcast_member_profile_stats").select("*").eq("user_id",id).maybeSingle();let following=false;if(u&&u.id!==id){const r=await crSupabase.from("podcast_member_follows").select("id").eq("follower_user_id",u.id).eq("followed_user_id",id).maybeSingle();following=!!r.data}shell('<section class="section wrap"><div class="card"><span class="eyebrow">CROWRULES MEMBER</span><h1>'+esc(p.display_name||p.username||"Member")+'</h1><p class="glow">@'+esc(p.username||"member")+'</p><p>'+esc(p.tagline||"")+'</p><p>'+esc(p.bio||"")+'</p><div class="grid"><div class="card"><small>CROWPOINTS</small><h2>'+Number(s?.crowpoints||0).toLocaleString()+'</h2></div><div class="card"><small>PODCASTS</small><h2>'+Number(s?.published_podcasts||0)+'</h2></div><div class="card"><small>EPISODES</small><h2>'+Number(s?.published_episodes||0)+'</h2></div><div class="card"><small>LISTENING</small><h2>'+Math.floor(Number(s?.listening_seconds||0)/3600)+'h</h2></div></div><div class="actions">'+(u&&u.id!==id?'<button class="btn '+(following?"":"primary")+'" onclick="toggleMemberFollow(\''+id+'\',this)">'+(following?"UNFOLLOW":"FOLLOW")+'</button>':"")+'<a class="btn" href="members.html">DISCOVER MEMBERS</a></div></div></section>')}

async function creatorFollowedEpisodes(u,mids){if(!mids.length)return{html:"",creatorIds:[]};const {data:cs}=await crSupabase.from("creators").select("id,name,member_id").in("member_id",mids).eq("is_active",true);const creators=cs||[],ids=creators.map(c=>c.id);if(!ids.length)return{html:"",creatorIds:[]};const {data:pods}=await crSupabase.from("podcasts").select("id,title,creator_id").in("creator_id",ids).eq("status","published");const p=pods||[],pids=p.map(x=>x.id);if(!pids.length)return{html:"",creatorIds:ids};const names=Object.fromEntries(creators.map(x=>[x.id,x.name]));const {data:eps}=await crSupabase.from("podcast_episodes").select("id,title,podcast_id,published_at").in("podcast_id",pids).eq("status","published").order("published_at",{ascending:false}).limit(25);const pnames=Object.fromEntries(p.map(x=>[x.id,x.title]));return{html:(eps||[]).map(e=>'<div class="card"><span class="eyebrow">CREATOR UPDATE</span><h3>'+esc(e.title)+'</h3><p>New episode from '+esc(names[p.find(x=>x.id===e.podcast_id)?.creator_id]||"a creator you follow")+' · '+esc(pnames[e.podcast_id]||"")+'</p><a class="btn primary" href="episode.html?id='+encodeURIComponent(e.id)+'">LISTEN</a></div>').join(""),creatorIds:ids,podcastIds:pids};}
async function activity(){const u=await user();if(!u){location.href="login.html";return}const {data:mf}=await crSupabase.from("podcast_member_follows").select("followed_user_id").eq("follower_user_id",u.id);const mids=(mf||[]).map(x=>x.followed_user_id);const {data:pf}=await crSupabase.from("podcast_follows").select("podcast_id").eq("user_id",u.id);const pids=(pf||[]).map(x=>x.podcast_id);let html='';const creatorUpdates=await creatorFollowedEpisodes(u,mids);html+=creatorUpdates.html;if(mids.length){const {data:profiles}=await crSupabase.from("podcast_member_profiles").select("user_id,display_name,username").in("user_id",mids).eq("is_public",true);(profiles||[]).forEach(p=>html+='<div class="card"><span class="eyebrow">NETWORK</span><h3>'+esc(p.display_name||p.username||"Member")+'</h3><p>You follow this member.</p><a class="btn" href="member-profile.html?id='+encodeURIComponent(p.user_id)+'">VIEW PROFILE</a></div>')}if(pids.length){const {data:eps}=await crSupabase.from("podcast_episodes").select("id,title,podcast_id,published_at").in("podcast_id",pids).eq("status","published").order("published_at",{ascending:false}).limit(25);(eps||[]).forEach(e=>html+='<div class="card"><span class="eyebrow">NEW EPISODE</span><h3>'+esc(e.title)+'</h3><p>From a podcast you follow.</p><a class="btn primary" href="episode.html?id='+encodeURIComponent(e.id)+'">LISTEN</a></div>')}const {data:notes}=await crSupabase.from("podcast_notifications").select("*").eq("user_id",u.id).order("created_at",{ascending:false}).limit(20);(notes||[]).forEach(n=>html+='<div class="card"><span class="eyebrow">NOTIFICATION</span><h3>'+esc(n.title||"CrowRules Update")+'</h3><p>'+esc(n.body||"")+'</p><small>'+new Date(n.created_at).toLocaleString()+'</small></div>');if(creatorUpdates.podcastIds?.length){crSupabase.channel("creator-activity-"+u.id).on("postgres_changes",{event:"INSERT",schema:"public",table:"podcast_episodes"},async payload=>{const e=payload.new;if(e?.status!=="published"||!creatorUpdates.podcastIds.includes(e.podcast_id))return;const el=document.createElement("div");el.className="card";el.innerHTML='<span class="eyebrow">LIVE CREATOR UPDATE</span><h3>'+esc(e.title||"New episode")+'</h3><p>A creator you follow just published an episode.</p><a class="btn primary" href="episode.html?id='+encodeURIComponent(e.id)+'">LISTEN</a>';document.querySelector(".grid")?.prepend(el)}).subscribe()};shell('<section class="section wrap"><span class="eyebrow">COMMUNITY ACTIVITY</span><h1>YOUR <span class="glow">ACTIVITY</span></h1><p>Updates from the people and podcasts you follow, plus your CrowRules notifications.</p><div class="actions"><a class="btn" href="feed.html">MY FEED</a><a class="btn" href="members.html">NETWORK</a><a class="btn" href="notifications.html">NOTIFICATIONS</a></div><div class="grid">'+(html||'<div class="card"><h3>Your activity feed is ready.</h3><p>Follow podcasts and members to start building your community activity.</p></div>')+'</div></section>')}
async function creatorCatalogHealth(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use Catalog Health.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,category,category_id,description,artwork_url,trailer_url,website_url,rss_url,status").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,description,published_at,duration_seconds,audio_url,thumbnail_url,transcript,show_notes,status").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const showChecks=p=>({title:!!p.title?.trim(),description:!!p.description?.trim(),artwork:!!p.artwork_url?.trim(),trailer:!!p.trailer_url?.trim(),website:!!p.website_url?.trim(),rss:!!p.rss_url?.trim(),category:!!(p.category?.trim()||p.category_id)});const episodeChecks=e=>({title:!!e.title?.trim(),description:!!e.description?.trim(),audio:!!e.audio_url?.trim(),published:!!e.published_at,thumbnail:!!e.thumbnail_url?.trim(),notes:!!e.show_notes?.trim(),transcript:!!e.transcript?.trim(),duration:Number(e.duration_seconds||0)>0});const showRows=shows.map(p=>{const missing=Object.entries(showChecks(p)).filter(([,v])=>!v).map(([k])=>k);return{p,missing}});const episodeRows=episodes.map(e=>{const missing=Object.entries(episodeChecks(e)).filter(([,v])=>!v).map(([k])=>k);return{e,missing}});const totalChecks=shows.length*7+episodes.length*8;const passed=showRows.reduce((n,x)=>n+7-x.missing.length,0)+episodeRows.reduce((n,x)=>n+8-x.missing.length,0);const health=totalChecks?Math.round(passed/totalChecks*100):0;const issues=showRows.filter(x=>x.missing.length).length+episodeRows.filter(x=>x.missing.length).length;const showCards=showRows.map(x=>'<div class="card"><span class="eyebrow">SHOW</span><h3>'+esc(x.p.title)+'</h3><p>'+esc(x.p.status||"draft")+' · '+(x.missing.length?'<strong>'+x.missing.length+' missing</strong>':'Catalog fields complete')+'</p><small>'+(x.missing.length?'Missing: '+esc(x.missing.join(", ")):'Title · description · artwork · catalog links checked')+'</small><div class="actions"><a class="btn" href="edit-podcast.html?id='+encodeURIComponent(x.p.id)+'">EDIT SHOW</a></div></div>').join("");const episodeCards=episodeRows.filter(x=>x.missing.length).slice(0,30).map(x=>'<div class="card"><span class="eyebrow">EPISODE</span><h3>'+esc(x.e.title)+'</h3><p>'+esc(x.e.status||"draft")+' · '+x.missing.length+' missing</p><small>Missing: '+esc(x.missing.join(", "))+'</small><div class="actions"><a class="btn" href="edit-episode.html?id='+encodeURIComponent(x.e.id)+'">EDIT EPISODE</a></div></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.27</span><h1>CATALOG <span class="glow">HEALTH</span></h1><p>Check whether your shows and episodes have the core metadata needed for a clean, production-ready catalog.</p><div class="actions"><a class="btn" href="podcast-dashboard.html">STUDIO</a><a class="btn" href="creator-content-intelligence.html">CONTENT INTELLIGENCE</a><a class="btn" href="creator-experiment-lab.html">EXPERIMENT LAB</a></div></div><div class="grid"><div class="card"><small>CATALOG HEALTH</small><h2>'+health+'%</h2></div><div class="card"><small>SHOWS</small><h2>'+shows.length+'</h2></div><div class="card"><small>EPISODES</small><h2>'+episodes.length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+episodes.filter(e=>e.status==="published").length+'</h2></div><div class="card"><small>ITEMS WITH ISSUES</small><h2>'+issues+'</h2></div></div><div class="card"><h3>Health rules</h3><p>Show checks cover title, description, artwork, trailer, website, RSS and category. Episode checks cover title, description, audio, publication date, thumbnail, show notes, transcript and duration. Show notes and transcripts improve catalog quality but are not publishing requirements.</p></div><h2 style="margin-top:55px">Show Health</h2><div class="grid">'+(showCards||'<p>No shows found.</p>')+'</div><h2 style="margin-top:55px">Episode Issues</h2><div class="grid">'+(episodeCards||'<div class="card"><h3>CATALOG LOOKS CLEAN</h3><p>No missing episode fields were found.</p></div>')+'</div></section>')};
async function creatorContentCalendar(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Content Calendar.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,published_at,created_at,episode_number,season_number").in("podcast_id",ids).order("published_at",{ascending:true,nullsFirst:false}).order("created_at",{ascending:true}).limit(300):{data:[]};const episodes=eps||[];const names=Object.fromEntries(shows.map(x=>[x.id,x.title]));const today=new Date();today.setHours(0,0,0,0);const end=new Date(today);end.setDate(end.getDate()+60);const groups={};episodes.forEach(e=>{const d=e.published_at?new Date(e.published_at):new Date(e.created_at);if(!Number.isNaN(d.getTime())){const key=d.toISOString().slice(0,10);(groups[key]??=[]).push(e)}});const statusCounts=episodes.reduce((a,e)=>{const s=e.status||"draft";a[s]=(a[s]||0)+1;return a},{});const upcoming=episodes.filter(e=>e.published_at&&new Date(e.published_at)>=today&&new Date(e.published_at)<=end).sort((a,b)=>new Date(a.published_at)-new Date(b.published_at));const monthStart=new Date(today.getFullYear(),today.getMonth(),1),firstDay=monthStart.getDay(),days=new Date(today.getFullYear(),today.getMonth()+1,0).getDate();let cells="";for(let i=0;i<firstDay;i++)cells+='<div class="card" style="min-height:90px;opacity:.25"></div>';for(let day=1;day<=days;day++){const dt=new Date(today.getFullYear(),today.getMonth(),day),key=dt.toISOString().slice(0,10),items=groups[key]||[];cells+='<div class="card" style="min-height:90px"><small>'+day+'</small>'+(items.length?items.map(e=>'<div style="margin-top:8px"><strong>'+esc(e.title)+'</strong><br><small>'+esc(names[e.podcast_id]||"Show")+' · '+esc(e.status||"draft")+'</small></div>').join(""):'<p style="opacity:.35;margin:8px 0 0">—</p>')+'</div>'}const cards=upcoming.slice(0,12).map(e=>'<div class="card"><span class="eyebrow">UPCOMING</span><h3>'+esc(e.title)+'</h3><p>'+esc(names[e.podcast_id]||"Show")+'</p><strong>'+new Date(e.published_at).toLocaleString([], {dateStyle:"medium",timeStyle:"short"})+'</strong><div class="actions"><a class="btn" href="edit-episode.html?id='+encodeURIComponent(e.id)+'">EDIT EPISODE</a></div></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.28</span><h1>CONTENT <span class="glow">CALENDAR</span></h1><p>See your published, scheduled and draft episodes in one planning workspace. This calendar is read-only and does not schedule or publish episodes.</p><div class="actions"><a class="btn" href="podcast-dashboard.html">STUDIO</a><a class="btn" href="creator-release-planner.html">RELEASE PLANNER</a><a class="btn" href="creator-programming-lab.html">PROGRAMMING LAB</a></div></div><div class="grid"><div class="card"><small>TOTAL EPISODES</small><h2>'+episodes.length+'</h2></div><div class="card"><small>DRAFTS</small><h2>'+Number(statusCounts.draft||0)+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+Number(statusCounts.published||0)+'</h2></div><div class="card"><small>NEXT 60 DAYS</small><h2>'+upcoming.length+'</h2></div></div><h2 style="margin-top:55px">'+today.toLocaleString([], {month:"long",year:"numeric"})+'</h2><div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px"><div><small>SUN</small></div><div><small>MON</small></div><div><small>TUE</small></div><div><small>WED</small></div><div><small>THU</small></div><div><small>FRI</small></div><div><small>SAT</small></div>'+cells+'</div><h2 style="margin-top:55px">Upcoming Releases</h2><div class="grid">'+(cards||'<div class="card"><h3>NO UPCOMING RELEASES</h3><p>Use the Release Planner to review your historical cadence.</p></div>')+'</div></section>')}

async function creatorProductionBoard(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Production Board.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,published_at,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const columns={draft:[],published:[],other:[]};episodes.forEach(e=>{if(e.status==="draft")columns.draft.push(e);else if(e.status==="published")columns.published.push(e);else columns.other.push(e)});const names=Object.fromEntries(shows.map(x=>[x.id,x.title]));const card=e=>'<div class="card"><span class="eyebrow">'+esc((e.status||"OTHER").toUpperCase())+'</span><h3>'+esc(e.title||"Untitled Episode")+'</h3><p>'+esc(names[e.podcast_id]||"Show")+'</p><small>'+(e.published_at?'Release: '+new Date(e.published_at).toLocaleString():'Created: '+new Date(e.created_at).toLocaleDateString())+'</small><div class="actions"><a class="btn" href="edit-episode.html?id='+encodeURIComponent(e.id)+'">EDIT</a></div></div>';shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.29</span><h1>PRODUCTION <span class="glow">BOARD</span></h1><p>A simple production workspace for moving episodes from draft to published. Status changes happen through the existing episode editor.</p><div class="actions"><a class="btn" href="podcast-dashboard.html">STUDIO</a><a class="btn" href="creator-content-calendar.html">CONTENT CALENDAR</a><a class="btn" href="creator-release-planner.html">RELEASE PLANNER</a><a class="btn primary" href="upload-episode.html">NEW EPISODE</a></div></div><div class="grid"><div class="card"><small>DRAFTS</small><h2>'+columns.draft.length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+columns.published.length+'</h2></div><div class="card"><small>OTHER STATUS</small><h2>'+columns.other.length+'</h2></div><div class="card"><small>SHOWS</small><h2>'+shows.length+'</h2></div></div><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:40px"><div><h2>DRAFT</h2>'+(columns.draft.map(card).join("")||'<div class="card"><p>No draft episodes.</p></div>')+'</div><div><h2>PUBLISHED</h2>'+(columns.published.slice(0,30).map(card).join("")||'<div class="card"><p>No published episodes.</p></div>')+'</div><div><h2>OTHER</h2>'+(columns.other.map(card).join("")||'<div class="card"><p>No episodes in another status.</p></div>')+'</div></div><div class="card" style="margin-top:40px"><h3>Production workflow</h3><p>Use Upload Episode or Edit Episode to manage the actual episode record. This board does not invent a scheduling field and does not automatically change publication status.</p></div></section>')}

async function creatorLaunchChecklist(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Launch Checklist.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,description,artwork_url,website_url,rss_url,status").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,description,audio_url,published_at,duration_seconds,status").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const checks=[["CREATOR PROFILE","Creator identity is connected",!!creator.id,"creator.html?id="+encodeURIComponent(creator.id)],["SHOW METADATA","At least one show exists",shows.length>0,"my-podcasts.html"],["SHOW DESCRIPTION","Every show has a description",shows.length>0&&shows.every(x=>x.description?.trim()),"my-podcasts.html"],["SHOW ARTWORK","Every show has artwork",shows.length>0&&shows.every(x=>x.artwork_url?.trim()),"my-podcasts.html"],["EPISODE","At least one episode exists",episodes.length>0,"my-episodes.html"],["EPISODE AUDIO","Every episode has audio",episodes.length>0&&episodes.every(x=>x.audio_url?.trim()),"my-episodes.html"],["EPISODE DESCRIPTION","Every episode has a description",episodes.length>0&&episodes.every(x=>x.description?.trim()),"my-episodes.html"],["EPISODE DURATION","Every episode has duration",episodes.length>0&&episodes.every(x=>Number(x.duration_seconds||0)>0),"my-episodes.html"],["PUBLISHED EPISODE","At least one episode is published",episodes.some(x=>x.status==="published"),"my-episodes.html"],["PUBLIC PAGE","Creator page is available",true,"creator.html?id="+encodeURIComponent(creator.id)]];const passed=checks.filter(x=>x[2]).length,pct=Math.round(passed/checks.length*100);const rows=checks.map(x=>'<div class="card"><span class="eyebrow">'+(x[2]?"READY":"ACTION NEEDED")+'</span><h3>'+esc(x[0])+'</h3><p>'+esc(x[1])+'</p><div class="actions"><a class="btn '+(x[2]?"":"primary")+'" href="'+x[3]+'">'+(x[2]?"VIEW":"FIX")+'</a></div></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.30</span><h1>LAUNCH <span class="glow">CHECKLIST</span></h1><p>A practical readiness checklist built from your existing creator, show and episode records. It does not publish or schedule anything.</p><div class="actions"><a class="btn" href="podcast-dashboard.html">STUDIO</a><a class="btn" href="creator-catalog-health.html">CATALOG HEALTH</a><a class="btn" href="creator-production-board.html">PRODUCTION BOARD</a><a class="btn primary" href="upload-episode.html">UPLOAD EPISODE</a></div></div><div class="grid"><div class="card"><small>READINESS</small><h2>'+pct+'%</h2></div><div class="card"><small>READY</small><h2>'+passed+'</h2></div><div class="card"><small>ACTION NEEDED</small><h2>'+(checks.length-passed)+'</h2></div><div class="card"><small>SHOWS</small><h2>'+shows.length+'</h2></div></div><div class="card"><h3>What this means</h3><p>100% means all checks on this page are satisfied by the current database records. It is a workflow checklist, not a guarantee that a show meets every external platform or distribution requirement.</p></div><div class="grid" style="margin-top:35px">'+rows+'</div></section>')}

async function creatorLaunchCenter(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Launch Center.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status,description,artwork_url").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const published=episodes.filter(e=>e.status==="published").length,drafts=episodes.filter(e=>e.status==="draft").length,withAudio=episodes.filter(e=>e.audio_url?.trim()).length,withDescription=episodes.filter(e=>e.description?.trim()).length;const showReady=shows.length>0&&shows.every(x=>x.title?.trim()&&x.description?.trim()&&x.artwork_url?.trim());const episodeReady=episodes.length>0&&episodes.every(e=>e.title?.trim()&&e.description?.trim()&&e.audio_url?.trim()&&Number(e.duration_seconds||0)>0);const checks=[!!creator.id,shows.length>0,showReady,episodes.length>0,episodeReady,published>0];const ready=checks.filter(Boolean).length,pct=Math.round(ready/checks.length*100);const next=published===0?"Publish your first episode":drafts>0?"Finish your draft episodes":!showReady?"Complete your show metadata":"Keep building your catalog";shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.31</span><h1>LAUNCH <span class="glow">CENTER</span></h1><p>Your single starting point for preparing, organizing and reviewing a CrowRules podcast before launch.</p><div class="actions"><a class="btn" href="podcast-dashboard.html">STUDIO</a><a class="btn" href="creator-launch-checklist.html">CHECKLIST</a><a class="btn" href="creator-production-board.html">PRODUCTION BOARD</a><a class="btn" href="creator-content-calendar.html">CALENDAR</a></div></div><div class="grid"><div class="card"><small>READINESS</small><h2>'+pct+'%</h2></div><div class="card"><small>SHOWS</small><h2>'+shows.length+'</h2></div><div class="card"><small>EPISODES</small><h2>'+episodes.length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+published+'</h2></div><div class="card"><small>DRAFTS</small><h2>'+drafts+'</h2></div><div class="card"><small>AUDIO READY</small><h2>'+withAudio+'</h2></div></div><div class="card"><span class="eyebrow">NEXT ACTION</span><h2>'+esc(next)+'</h2><p>Use the workflow tools below to move from preparation to publication.</p><div class="actions"><a class="btn primary" href="'+(published===0?"upload-episode.html":drafts>0?"my-episodes.html":"creator-catalog-health.html")+'">OPEN NEXT STEP</a></div></div><h2 style="margin-top:50px">Launch Workflow</h2><div class="grid"><div class="card"><span class="eyebrow">01 · BUILD</span><h3>Creator Identity</h3><p>Manage your creator profile and public identity.</p><a class="btn" href="profile.html">PROFILE</a></div><div class="card"><span class="eyebrow">02 · SHOW</span><h3>Podcast Setup</h3><p>Create and manage your shows.</p><a class="btn" href="my-podcasts.html">MY SHOWS</a></div><div class="card"><span class="eyebrow">03 · PRODUCE</span><h3>Episodes</h3><p>Create, upload and edit episodes.</p><a class="btn" href="my-episodes.html">MY EPISODES</a></div><div class="card"><span class="eyebrow">04 · REVIEW</span><h3>Catalog Health</h3><p>Check metadata and production readiness.</p><a class="btn" href="creator-catalog-health.html">HEALTH</a></div><div class="card"><span class="eyebrow">05 · PLAN</span><h3>Release Planning</h3><p>Review cadence and organize releases.</p><a class="btn" href="creator-release-planner.html">PLANNER</a></div><div class="card"><span class="eyebrow">06 · LAUNCH</span><h3>Readiness Checklist</h3><p>Review the final workflow checks.</p><a class="btn" href="creator-launch-checklist.html">CHECKLIST</a></div></div><div class="card" style="margin-top:35px"><h3>Readiness note</h3><p>This center uses existing CrowRules database records. It does not publish, schedule, distribute or submit a podcast automatically.</p></div></section>')}

async function creatorLaunchQueue(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Launch Queue.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const names=Object.fromEntries(shows.map(x=>[x.id,x.title]));const queue=episodes.filter(e=>e.status!=="published").map(e=>{const blockers=[];if(!e.title?.trim())blockers.push("title");if(!e.description?.trim())blockers.push("description");if(!e.audio_url?.trim())blockers.push("audio");if(!(Number(e.duration_seconds||0)>0))blockers.push("duration");return{e,blockers}}).sort((a,b)=>a.blockers.length-b.blockers.length);const ready=queue.filter(x=>!x.blockers.length).length;const cards=queue.slice(0,30).map(x=>'<div class="card"><span class="eyebrow">'+(x.blockers.length?'ACTION NEEDED':'READY TO REVIEW')+'</span><h3>'+esc(x.e.title||"Untitled Episode")+'</h3><p>'+esc(names[x.e.podcast_id]||"Show")+' · '+esc(x.e.status||"draft")+'</p><small>'+(x.blockers.length?'Missing: '+esc(x.blockers.join(", ")):'Core production fields complete')+'</small><div class="actions"><a class="btn '+(x.blockers.length?'primary':'')+'" href="edit-episode.html?id='+encodeURIComponent(x.e.id)+'">EDIT</a></div></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.32</span><h1>LAUNCH <span class="glow">QUEUE</span></h1><p>A focused queue of unpublished episodes, ordered by production readiness so you can work through the catalog one episode at a time.</p><div class="actions"><a class="btn" href="creator-launch-center.html">LAUNCH CENTER</a><a class="btn" href="creator-launch-checklist.html">CHECKLIST</a><a class="btn" href="creator-production-board.html">PRODUCTION BOARD</a><a class="btn primary" href="upload-episode.html">NEW EPISODE</a></div></div><div class="grid"><div class="card"><small>UNPUBLISHED</small><h2>'+queue.length+'</h2></div><div class="card"><small>READY TO REVIEW</small><h2>'+ready+'</h2></div><div class="card"><small>NEEDS WORK</small><h2>'+(queue.length-ready)+'</h2></div><div class="card"><small>SHOWS</small><h2>'+shows.length+'</h2></div></div><div class="card"><h3>How the queue works</h3><p>Episodes are grouped from your existing records. Core checks are title, description, audio and duration. This page does not publish, schedule or change status.</p></div><div class="grid" style="margin-top:35px">'+(cards||'<div class="card"><h3>QUEUE EMPTY</h3><p>There are no unpublished episodes in your current catalog.</p></div>')+'</div></section>')}

async function creatorPrePublishReview(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use Pre-Publish Review.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status,description,artwork_url,website_url,rss_url").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).neq("status","published").order("created_at",{ascending:false}).limit(100):{data:[]};const episodes=eps||[];const rows=episodes.map(e=>{const checks=[["Title",!!e.title?.trim()],["Description",!!e.description?.trim()],["Audio",!!e.audio_url?.trim()],["Duration",Number(e.duration_seconds||0)>0],["Status",!!e.status]];const passed=checks.filter(x=>x[1]).length;return{e,checks,passed,pct:Math.round(passed/checks.length*100)}});const ready=rows.filter(x=>x.pct===100).length;const cards=rows.map(x=>'<div class="card"><span class="eyebrow">'+(x.pct===100?"READY":"REVIEW")+'</span><h3>'+esc(x.e.title||"Untitled Episode")+'</h3><p>'+esc(shows.find(s=>s.id===x.e.podcast_id)?.title||"Show")+' · '+esc(x.e.status||"draft")+'</p><h2>'+x.pct+'%</h2><p>'+x.checks.map(c=>(c[1]?"✓ ":"✕ ")+esc(c[0])).join(" · ")+'</p><a class="btn '+(x.pct===100?"primary":"")+'" href="edit-episode.html?id='+encodeURIComponent(x.e.id)+'">OPEN EDITOR</a></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.33</span><h1>PRE-PUBLISH <span class="glow">REVIEW</span></h1><p>Review every unpublished episode against the core production fields before changing its status.</p><div class="actions"><a class="btn" href="creator-launch-queue.html">LAUNCH QUEUE</a><a class="btn" href="creator-launch-checklist.html">CHECKLIST</a><a class="btn" href="creator-catalog-health.html">CATALOG HEALTH</a><a class="btn primary" href="my-episodes.html">MY EPISODES</a></div></div><div class="grid"><div class="card"><small>UNPUBLISHED</small><h2>'+rows.length+'</h2></div><div class="card"><small>READY</small><h2>'+ready+'</h2></div><div class="card"><small>NEEDS REVIEW</small><h2>'+(rows.length-ready)+'</h2></div><div class="card"><small>SHOWS</small><h2>'+shows.length+'</h2></div></div><div class="card"><h3>Review standard</h3><p>An episode is marked READY when title, description, audio, duration and status are present. This is a CrowRules workflow check, not a certification for external podcast platforms.</p></div><div class="grid" style="margin-top:35px">'+(cards||'<div class="card"><h3>NO UNPUBLISHED EPISODES</h3><p>Your current catalog has no unpublished episodes to review.</p></div>')+'</div></section>')}

async function creatorLaunchSummary(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use Launch Summary.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status,description,artwork_url").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const pub=episodes.filter(e=>e.status==="published"),draft=episodes.filter(e=>e.status==="draft"),other=episodes.filter(e=>e.status!=="published"&&e.status!=="draft");const complete=episodes.filter(e=>e.title?.trim()&&e.description?.trim()&&e.audio_url?.trim()&&Number(e.duration_seconds||0)>0);const showComplete=shows.filter(s=>s.title?.trim()&&s.description?.trim()&&s.artwork_url?.trim()).length;const pct=episodes.length?Math.round(complete.length/episodes.length*100):0;const recent=pub.slice(0,8).map(e=>'<div class="card"><span class="eyebrow">PUBLISHED</span><h3>'+esc(e.title||"Untitled")+'</h3><p>'+esc(shows.find(s=>s.id===e.podcast_id)?.title||"Show")+'</p><small>'+(e.published_at?new Date(e.published_at).toLocaleDateString():"No date")+'</small></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.34</span><h1>LAUNCH <span class="glow">SUMMARY</span></h1><p>A compact launch-readiness overview combining your existing show and episode records.</p><div class="actions"><a class="btn" href="creator-launch-center.html">LAUNCH CENTER</a><a class="btn" href="creator-pre-publish-review.html">PRE-PUBLISH REVIEW</a><a class="btn" href="creator-launch-queue.html">LAUNCH QUEUE</a><a class="btn primary" href="my-episodes.html">MY EPISODES</a></div></div><div class="grid"><div class="card"><small>EPISODE READINESS</small><h2>'+pct+'%</h2></div><div class="card"><small>SHOWS READY</small><h2>'+showComplete+'/'+shows.length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+pub.length+'</h2></div><div class="card"><small>DRAFTS</small><h2>'+draft.length+'</h2></div><div class="card"><small>OTHER</small><h2>'+other.length+'</h2></div><div class="card"><small>TOTAL EPISODES</small><h2>'+episodes.length+'</h2></div></div><div class="card"><span class="eyebrow">LAUNCH STATE</span><h2>'+(!shows.length?"BUILD YOUR FIRST SHOW":!episodes.length?"CREATE YOUR FIRST EPISODE":!pub.length?"PREPARE YOUR FIRST PUBLISHED EPISODE":draft.length?"CONTINUE PRODUCTION":"CATALOG ACTIVE")+'</h2><p>This summary reflects database records available to your creator account. It does not certify external distribution requirements or automatically publish anything.</p></div><h2 style="margin-top:50px">Recent Published Episodes</h2><div class="grid">'+(recent||'<div class="card"><h3>NO PUBLISHED EPISODES</h3><p>Your catalog does not currently contain published episodes.</p></div>')+'</div></section>')}

async function creatorLaunchReport(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Launch Report.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,status,description,artwork_url").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(s=>s.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const published=episodes.filter(e=>e.status==="published"),unpublished=episodes.filter(e=>e.status!=="published");const showChecks=shows.map(s=>({s,missing:[!s.description&&"description",!s.artwork_url&&"artwork"].filter(Boolean)}));const epChecks=episodes.map(e=>({e,missing:[!e.title&&"title",!e.description&&"description",!e.audio_url&&"audio",!(Number(e.duration_seconds||0)>0)&&"duration"].filter(Boolean)}));const showReady=showChecks.filter(x=>!x.missing.length).length,epReady=epChecks.filter(x=>!x.missing.length).length;const overall=shows.length+episodes.length?Math.round((showReady+epReady)/(shows.length+episodes.length)*100):0;const issues=[...showChecks.filter(x=>x.missing.length).map(x=>'<div class="card"><span class="eyebrow">SHOW</span><h3>'+esc(x.s.title)+'</h3><p>Missing: '+esc(x.missing.join(", "))+'</p><a class="btn" href="edit-podcast.html?id='+encodeURIComponent(x.s.id)+'">EDIT SHOW</a></div>'),...epChecks.filter(x=>x.missing.length).slice(0,30).map(x=>'<div class="card"><span class="eyebrow">EPISODE</span><h3>'+esc(x.e.title||"Untitled Episode")+'</h3><p>Missing: '+esc(x.missing.join(", "))+'</p><a class="btn" href="edit-episode.html?id='+encodeURIComponent(x.e.id)+'">EDIT EPISODE</a></div>')].join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.35</span><h1>LAUNCH <span class="glow">REPORT</span></h1><p>One-page production report showing what is complete, what remains, and where to make the next fix.</p><div class="actions"><a class="btn" href="creator-launch-summary.html">SUMMARY</a><a class="btn" href="creator-pre-publish-review.html">PRE-PUBLISH REVIEW</a><a class="btn" href="creator-launch-queue.html">LAUNCH QUEUE</a><a class="btn primary" href="creator-launch-center.html">LAUNCH CENTER</a></div></div><div class="grid"><div class="card"><small>OVERALL READINESS</small><h2>'+overall+'%</h2></div><div class="card"><small>SHOWS READY</small><h2>'+showReady+'/'+shows.length+'</h2></div><div class="card"><small>EPISODES READY</small><h2>'+epReady+'/'+episodes.length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+published.length+'</h2></div><div class="card"><small>UNPUBLISHED</small><h2>'+unpublished.length+'</h2></div></div><div class="card"><span class="eyebrow">REPORT NOTE</span><p>Readiness is based only on the internal CrowRules fields checked here. It is not an external distribution certification.</p></div><h2 style="margin-top:50px">Items Requiring Attention</h2><div class="grid">'+(issues||'<div class="card"><h3>NO CORE ISSUES FOUND</h3><p>The current show and episode records pass this report.</p></div>')+'</div></section>')}

async function creatorEpisodeWorkspace(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Episode Workspace.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const id=new URLSearchParams(location.search).get("id");if(!id){shell('<section class="section wrap"><div class="form"><h2>EPISODE WORKSPACE</h2><p>Select an episode from My Episodes or the Launch Queue.</p><a class="btn primary" href="my-episodes.html">MY EPISODES</a></div></section>');return}const {data:e,error}=await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").eq("id",id).maybeSingle();if(error||!e){shell('<section class="section wrap"><div class="form"><h2>EPISODE NOT FOUND</h2><p>This episode could not be loaded.</p><a class="btn primary" href="my-episodes.html">MY EPISODES</a></div></section>');return}const {data:show}=await crSupabase.from("podcasts").select("id,title,creator_id").eq("id",e.podcast_id).maybeSingle();if(!show||show.creator_id!==creator.id){shell('<section class="section wrap"><div class="form"><h2>ACCESS CHECK</h2><p>This episode is not part of your creator catalog.</p><a class="btn primary" href="my-episodes.html">MY EPISODES</a></div></section>');return}const checks=[["Title",!!e.title?.trim()],["Description",!!e.description?.trim()],["Audio",!!e.audio_url?.trim()],["Duration",Number(e.duration_seconds||0)>0],["Status",!!e.status]];const ready=checks.filter(x=>x[1]).length;const pct=Math.round(ready/checks.length*100);const state=e.status==="published"?"PUBLISHED":pct===100?"READY FOR REVIEW":"IN PRODUCTION";shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.36</span><h1>EPISODE <span class="glow">WORKSPACE</span></h1><p>'+esc(show.title)+' · '+esc(e.title||"Untitled Episode")+'</p><div class="actions"><a class="btn" href="my-episodes.html">MY EPISODES</a><a class="btn" href="creator-launch-queue.html">LAUNCH QUEUE</a><a class="btn" href="creator-pre-publish-review.html">PRE-PUBLISH REVIEW</a><a class="btn primary" href="edit-episode.html?id='+encodeURIComponent(e.id)+'">EDIT EPISODE</a></div></div><div class="grid"><div class="card"><small>STATE</small><h2>'+state+'</h2></div><div class="card"><small>READINESS</small><h2>'+pct+'%</h2></div><div class="card"><small>STATUS</small><h2>'+esc(e.status||"draft")+'</h2></div><div class="card"><small>DURATION</small><h2>'+((Number(e.duration_seconds||0)/60).toFixed(1))+' MIN</h2></div></div><div class="grid"><div class="card"><h3>PRODUCTION CHECKS</h3><p>'+checks.map(c=>(c[1]?"✓ ":"✕ ")+esc(c[0])).join("<br>")+'</p></div><div class="card"><h3>EPISODE DETAILS</h3><p>Created: '+(e.created_at?new Date(e.created_at).toLocaleString():"—")+'<br>Published: '+(e.published_at?new Date(e.published_at).toLocaleString():"Not published")+'</p><a class="btn" href="community.html?id='+encodeURIComponent(e.id)+'">COMMUNITY</a></div></div><div class="card"><span class="eyebrow">WORKFLOW</span><p>Build metadata → verify audio → review readiness → edit as needed → use the existing episode status workflow. This workspace is read-only and does not publish or change the episode.</p></div></section>')}

async function creatorEpisodeReviewBoard(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Episode Review Board.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(s=>s.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const groups={published:[],ready:[],review:[]};episodes.forEach(e=>{if(e.status==="published")groups.published.push(e);else if(e.title?.trim()&&e.description?.trim()&&e.audio_url?.trim()&&Number(e.duration_seconds||0)>0)groups.ready.push(e);else groups.review.push(e)});const name=id=>shows.find(s=>s.id===id)?.title||"Show";const cards=(arr,cls)=>arr.slice(0,30).map(e=>'<div class="card"><span class="eyebrow">'+cls+'</span><h3>'+esc(e.title||"Untitled Episode")+'</h3><p>'+esc(name(e.podcast_id))+' · '+esc(e.status||"draft")+'</p><a class="btn" href="creator-episode-workspace.html?id='+encodeURIComponent(e.id)+'">WORKSPACE</a></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.37</span><h1>EPISODE REVIEW <span class="glow">BOARD</span></h1><p>A visual board for moving episodes through production review without changing their status automatically.</p><div class="actions"><a class="btn" href="creator-episode-workspace.html">WORKSPACE</a><a class="btn" href="creator-pre-publish-review.html">PRE-PUBLISH REVIEW</a><a class="btn" href="creator-launch-queue.html">LAUNCH QUEUE</a><a class="btn primary" href="upload-episode.html">NEW EPISODE</a></div></div><div class="grid"><div class="card"><small>PUBLISHED</small><h2>'+groups.published.length+'</h2></div><div class="card"><small>READY</small><h2>'+groups.ready.length+'</h2></div><div class="card"><small>NEEDS REVIEW</small><h2>'+groups.review.length+'</h2></div><div class="card"><small>TOTAL</small><h2>'+episodes.length+'</h2></div></div><div class="grid" style="margin-top:35px"><div><h2>NEEDS REVIEW</h2>'+(cards(groups.review,"ACTION NEEDED")||'<div class="card"><p>No episodes need core metadata/audio review.</p></div>')+'</div><div><h2>READY</h2>'+(cards(groups.ready,"READY FOR REVIEW")||'<div class="card"><p>No episodes are currently ready.</p></div>')+'</div><div><h2>PUBLISHED</h2>'+(cards(groups.published,"PUBLISHED")||'<div class="card"><p>No published episodes yet.</p></div>')+'</div></div></section>')}

async function creatorEpisodeHandoff(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Episode Handoff Center.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title").eq("creator_id",creator.id).order("created_at",{ascending:false});const shows=pods||[];const ids=shows.map(s=>s.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const groups={build:[],review:[],ready:[],published:[]};episodes.forEach(e=>{if(e.status==="published")groups.published.push(e);else if(!e.title?.trim()||!e.description?.trim()||!e.audio_url?.trim()||Number(e.duration_seconds||0)<=0)groups.build.push(e);else if(!e.published_at)groups.review.push(e);else groups.ready.push(e)});const showName=id=>shows.find(s=>s.id===id)?.title||"Show";const card=e=>'<div class="card"><span class="eyebrow">'+(e.status==="published"?"PUBLISHED":groups.build.includes(e)?"BUILD":"HANDOFF")+'</span><h3>'+esc(e.title||"Untitled Episode")+'</h3><p>'+esc(showName(e.podcast_id))+' · '+esc(e.status||"draft")+'</p><a class="btn primary" href="creator-episode-workspace.html?id='+encodeURIComponent(e.id)+'">OPEN WORKSPACE</a></div>';shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.38</span><h1>EPISODE <span class="glow">HANDOFF</span></h1><p>Move each episode from production into review using the existing CrowRules workflow.</p><div class="actions"><a class="btn" href="creator-episode-review-board.html">REVIEW BOARD</a><a class="btn" href="creator-launch-summary.html">LAUNCH SUMMARY</a><a class="btn" href="creator-pre-publish-review.html">PRE-PUBLISH REVIEW</a><a class="btn primary" href="upload-episode.html">NEW EPISODE</a></div></div><div class="grid"><div class="card"><small>BUILD</small><h2>'+groups.build.length+'</h2><p>Missing core production fields</p></div><div class="card"><small>HANDOFF</small><h2>'+groups.review.length+'</h2><p>Ready to move into review</p></div><div class="card"><small>READY</small><h2>'+groups.ready.length+'</h2><p>Prepared episodes</p></div><div class="card"><small>PUBLISHED</small><h2>'+groups.published.length+'</h2></div></div><div class="grid" style="margin-top:35px"><div><h2>BUILD</h2>'+ (groups.build.slice(0,20).map(card).join("")||'<div class="card"><p>Nothing in build.</p></div>')+'</div><div><h2>HANDOFF</h2>'+ (groups.review.slice(0,20).map(card).join("")||'<div class="card"><p>No episodes waiting for handoff.</p></div>')+'</div><div><h2>READY / PUBLISHED</h2>'+ (groups.ready.concat(groups.published).slice(0,20).map(card).join("")||'<div class="card"><p>No episodes here yet.</p></div>')+'</div></div><div class="card" style="margin-top:25px"><span class="eyebrow">READ-ONLY WORKFLOW</span><p>This center organizes existing episode records. It does not publish, schedule, or change episode status.</p></div></section>')}

async function creatorEpisodeMetrics(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use Episode Metrics.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title").eq("creator_id",creator.id);const shows=pods||[],ids=shows.map(x=>x.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[],eids=episodes.map(x=>x.id);const {data:listens}=eids.length?await crSupabase.from("podcast_listens").select("episode_id,seconds_listened,completed").in("episode_id",eids):{data:[]};const {data:comments}=eids.length?await crSupabase.from("podcast_episode_comments").select("episode_id").in("episode_id",eids).eq("status","approved"): {data:[]};const {data:reactions}=eids.length?await crSupabase.from("podcast_episode_reactions").select("episode_id").in("episode_id",eids):{data:[]};const {data:saves}=eids.length?await crSupabase.from("podcast_saved_episodes").select("episode_id").in("episode_id",eids):{data:[]};const count=(arr,id)=>arr.filter(x=>x.episode_id===id).length;const showName=id=>shows.find(s=>s.id===id)?.title||"Show";const cards=episodes.slice(0,50).map(e=>{const ls=listens||[],l=ls.filter(x=>x.episode_id===e.id),sec=l.reduce((n,x)=>n+Number(x.seconds_listened||0),0),done=l.filter(x=>x.completed).length,comp=l.length?Math.round(done/l.length*100):0;return '<div class="card"><span class="eyebrow">'+esc(e.status||"draft")+'</span><h3>'+esc(e.title||"Untitled Episode")+'</h3><p>'+esc(showName(e.podcast_id))+'</p><div class="grid"><div><small>LISTENS</small><h2>'+l.length+'</h2></div><div><small>MINUTES</small><h2>'+Math.round(sec/60)+'</h2></div><div><small>COMPLETION</small><h2>'+comp+'%</h2></div><div><small>COMMUNITY</small><h2>'+(count(comments||[],e.id)+count(reactions||[],e.id)+count(saves||[],e.id))+'</h2></div></div><a class="btn" href="creator-episode-workspace.html?id='+encodeURIComponent(e.id)+'">WORKSPACE</a></div>'}).join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.39</span><h1>EPISODE <span class="glow">METRICS</span></h1><p>Episode-level listening and community activity from recorded CrowRules data.</p><div class="actions"><a class="btn" href="creator-analytics.html">ANALYTICS</a><a class="btn" href="creator-engagement.html">ENGAGEMENT</a><a class="btn" href="creator-insights.html">INSIGHTS</a><a class="btn primary" href="creator-episode-review-board.html">REVIEW BOARD</a></div></div><div class="grid"><div class="card"><small>EPISODES</small><h2>'+episodes.length+'</h2></div><div class="card"><small>LISTEN SESSIONS</small><h2>'+(listens||[]).length+'</h2></div><div class="card"><small>LISTEN MINUTES</small><h2>'+Math.round((listens||[]).reduce((n,x)=>n+Number(x.seconds_listened||0),0)/60)+'</h2></div><div class="card"><small>COMMUNITY ACTIONS</small><h2>'+((comments||[]).length+(reactions||[]).length+(saves||[]).length)+'</h2></div></div><div class="grid" style="margin-top:30px">'+(cards||'<div class="card"><p>No episodes found.</p></div>')+'</div><div class="card" style="margin-top:25px"><span class="eyebrow">DATA NOTE</span><p>Metrics reflect rows currently available to the signed-in creator through existing CrowRules tables. Anonymous activity and unavailable rows are not inferred.</p></div></section>')}

async function creatorEpisodeHealth(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use Episode Health.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title").eq("creator_id",creator.id);const shows=pods||[],ids=shows.map(s=>s.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).limit(300):{data:[]};const episodes=eps||[];const rows=episodes.map(e=>{const checks=[!!e.title?.trim(),!!e.description?.trim(),!!e.audio_url?.trim(),Number(e.duration_seconds||0)>0,!!e.status];return {...e,score:Math.round(checks.filter(Boolean).length/checks.length*100),missing:checks.map((v,i)=>v?null:["title","description","audio","duration","status"][i]).filter(Boolean)}});const avg=rows.length?Math.round(rows.reduce((n,e)=>n+e.score,0)/rows.length):0;const healthy=rows.filter(e=>e.score===100).length,action=rows.filter(e=>e.score<100).length;const showName=id=>shows.find(s=>s.id===id)?.title||"Show";const cards=rows.sort((a,b)=>a.score-b.score).slice(0,50).map(e=>'<div class="card"><span class="eyebrow">'+(e.score===100?"HEALTHY":"ACTION NEEDED")+'</span><h3>'+esc(e.title||"Untitled Episode")+'</h3><p>'+esc(showName(e.podcast_id))+' · '+esc(e.status||"draft")+'</p><h2>'+e.score+'%</h2><p>'+ (e.missing.length? "Missing: "+e.missing.join(", "):"All core fields present")+'</p><a class="btn" href="creator-episode-workspace.html?id='+encodeURIComponent(e.id)+'">WORKSPACE</a></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.40</span><h1>EPISODE <span class="glow">HEALTH</span></h1><p>A simple catalog health check for every episode in your creator catalog.</p><div class="actions"><a class="btn" href="creator-catalog-health.html">CATALOG HEALTH</a><a class="btn" href="creator-episode-metrics.html">EPISODE METRICS</a><a class="btn" href="creator-episode-review-board.html">REVIEW BOARD</a><a class="btn primary" href="creator-episode-workspace.html">WORKSPACE</a></div></div><div class="grid"><div class="card"><small>EPISODES</small><h2>'+episodes.length+'</h2></div><div class="card"><small>AVERAGE HEALTH</small><h2>'+avg+'%</h2></div><div class="card"><small>HEALTHY</small><h2>'+healthy+'</h2></div><div class="card"><small>ACTION NEEDED</small><h2>'+action+'</h2></div></div><div class="grid" style="margin-top:30px">'+(cards||'<div class="card"><p>No episodes found.</p></div>')+'</div><div class="card" style="margin-top:25px"><span class="eyebrow">DATA NOTE</span><p>Health is based only on the five core episode fields checked here. It is an internal CrowRules workflow indicator, not a certification by an external podcast platform.</p></div></section>')}

async function creatorEpisodeFinalGate(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Create or connect a creator profile to use the Final Gate.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,description,artwork_url").eq("creator_id",creator.id);const shows=pods||[],ids=shows.map(s=>s.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,audio_url,description,published_at,duration_seconds,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const checks=e=>{const items=[["Title",!!e.title?.trim()],["Description",!!e.description?.trim()],["Audio",!!e.audio_url?.trim()],["Duration",Number(e.duration_seconds||0)>0],["Status",!!e.status]];return {items,score:Math.round(items.filter(x=>x[1]).length/items.length*100)}};const rows=episodes.map(e=>({...e,gate:checks(e)}));const eligible=rows.filter(e=>e.gate.score===100&&e.status!=="published");const published=rows.filter(e=>e.status==="published").length;const showReady=shows.filter(s=>s.description?.trim()&&s.artwork_url?.trim()).length;const gateReady=eligible.length;const cards=rows.slice(0,50).map(e=>{const g=e.gate;return '<div class="card"><span class="eyebrow">'+(g.score===100?(e.status==="published"?"PUBLISHED":"FINAL GATE READY"):"BLOCKED")+'</span><h3>'+esc(e.title||"Untitled Episode")+'</h3><p>'+esc(shows.find(s=>s.id===e.podcast_id)?.title||"Show")+'</p><h2>'+g.score+'%</h2><div>'+g.items.map(x=>'<p style="margin:.35rem 0">'+(x[1]?"✓ ":"✕ ")+esc(x[0])+'</p>').join("")+'</div><a class="btn" href="creator-episode-workspace.html?id='+encodeURIComponent(e.id)+'">OPEN WORKSPACE</a></div>'}).join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.41</span><h1>FINAL <span class="glow">GATE</span></h1><p>One final read-only checkpoint before an episode moves beyond production.</p><div class="actions"><a class="btn" href="creator-episode-health.html">EPISODE HEALTH</a><a class="btn" href="creator-pre-publish-review.html">PRE-PUBLISH REVIEW</a><a class="btn" href="creator-episode-handoff.html">HANDOFF</a><a class="btn primary" href="creator-launch-center.html">LAUNCH CENTER</a></div></div><div class="grid"><div class="card"><small>EPISODES</small><h2>'+episodes.length+'</h2></div><div class="card"><small>FINAL-GATE READY</small><h2>'+gateReady+'</h2></div><div class="card"><small>SHOWS WITH CORE METADATA</small><h2>'+showReady+'/'+shows.length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+published+'</h2></div></div><div class="card" style="margin-top:30px"><span class="eyebrow">FINAL CHECK</span><p>An episode is shown as FINAL GATE READY when all five core episode fields are present and its status is not published. This page does not publish, schedule, approve, or change records.</p></div><div class="grid" style="margin-top:25px">'+(cards||'<div class="card"><p>No episodes found.</p></div>')+'</div></section>')}

