async function creatorStudioReleaseReadiness(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Connect a creator profile to open Release Readiness.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,description,artwork_url").eq("creator_id",creator.id).limit(100);const shows=pods||[],ids=shows.map(p=>p.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,description,audio_url,duration_seconds,status,published_at,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const complete=e=>!!e.title?.trim()&&!!e.description?.trim()&&!!e.audio_url?.trim()&&Number(e.duration_seconds||0)>0;const checks=[["SHOW EXISTS",shows.length>0,"Create a podcast show.","create-podcast.html"],["SHOW METADATA",shows.length>0&&shows.every(p=>p.title?.trim()&&p.description?.trim()&&p.artwork_url?.trim()),"Complete show title, description, and artwork.","my-podcasts.html"],["EPISODE EXISTS",episodes.length>0,"Create the first episode.","upload-episode.html"],["EPISODE READY",episodes.length>0&&episodes.some(complete),"Complete core episode fields and audio.","creator-episode-health.html"],["REVIEW QUEUE",episodes.some(e=>complete(e)&&e.status!=="published"&&!e.published_at),"Review a completed episode before release.","creator-episode-review-board.html"]];const published=episodes.some(e=>e.status==="published");const ready=checks.slice(0,4).every(c=>c[1])&&checks[4][1];const rows=checks.map((c,i)=>'<div class="card"><span class="eyebrow">0'+(i+1)+' · '+(c[1]?'READY':'OPEN')+'</span><h2>'+esc(c[0])+'</h2><p>'+esc(c[1]?'Requirement detected in the current catalog.':c[2])+'</p>'+(!c[1]?'<a class="btn primary" href="'+c[3]+'">OPEN FIX</a>':'')+'</div>').join("");const state=published?'ACTIVE':ready?'READY FOR REVIEW':checks[0][1]?'IN PRODUCTION':'FOUNDATION';shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.71</span><h1>RELEASE <span class="glow">READINESS</span></h1><p>Verify the concrete prerequisites around your next podcast release.</p><div class="actions"><a class="btn primary" href="creator-launch-center.html">LAUNCH CENTER</a><a class="btn" href="creator-studio-health-alerts.html">HEALTH ALERTS</a><a class="btn" href="creator-studio.html">STUDIO HOME</a></div></div><div class="card"><span class="eyebrow">CURRENT STATE</span><h2>'+esc(state)+'</h2><p>'+ (published?'A published episode exists in the current catalog.':ready?'The catalog has the core prerequisites for review.':'Complete the open prerequisites shown below.')+'</p></div><div class="grid" style="margin-top:25px">'+rows+'</div><div class="card" style="margin-top:30px"><span class="eyebrow">READ-ONLY</span><p>This readiness view checks existing records only. It does not publish, schedule, or modify content.</p></div></section>')}
