async function creatorStudioReleaseMap(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Connect a creator profile to open the Release Map.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title,description,artwork_url,created_at").eq("creator_id",creator.id).order("created_at",{ascending:false}).limit(100);const shows=pods||[],ids=shows.map(p=>p.id);const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,status,published_at,created_at,audio_url,duration_seconds").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const byShow={};episodes.forEach(e=>(byShow[e.podcast_id]??=[]).push(e));const card=p=>{const es=byShow[p.id]||[],pub=es.filter(e=>e.status==="published").length,ready=es.filter(e=>e.audio_url&&Number(e.duration_seconds||0)>0&&e.status!=="published").length,work=es.filter(e=>!e.title?.trim()||!e.audio_url?.trim()||Number(e.duration_seconds||0)<=0).length;return '<div class="card"><span class="eyebrow">SHOW</span><h2>'+esc(p.title||"Untitled show")+'</h2><div class="stats"><span><b>'+es.length+'</b> episodes</span><span><b>'+pub+'</b> published</span><span><b>'+ready+'</b> ready</span></div><p>'+esc(work?'Production work remains on '+work+' episode(s).':pub?'Published catalog is active.':'No published episodes yet.')+'</p><div class="actions"><a class="btn primary" href="edit-podcast.html?id='+encodeURIComponent(p.id)+'">OPEN SHOW</a><a class="btn" href="creator-episode-workspace.html">EPISODE WORKSPACE</a></div></div>'};const pub=episodes.filter(e=>e.status==="published").length;const ready=episodes.filter(e=>e.audio_url&&Number(e.duration_seconds||0)>0&&e.status!=="published").length;shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.72</span><h1>RELEASE <span class="glow">MAP</span></h1><p>A show-by-show view of where your catalog currently stands on the path to release.</p><div class="actions"><a class="btn primary" href="creator-studio-release-readiness.html">READINESS</a><a class="btn" href="creator-studio-priorities.html">PRIORITIES</a><a class="btn" href="creator-studio.html">STUDIO HOME</a></div></div><div class="grid"><div class="card"><span class="eyebrow">SHOWS</span><h2>'+shows.length+'</h2></div><div class="card"><span class="eyebrow">EPISODES</span><h2>'+episodes.length+'</h2></div><div class="card"><span class="eyebrow">READY</span><h2>'+ready+'</h2></div><div class="card"><span class="eyebrow">PUBLISHED</span><h2>'+pub+'</h2></div></div><div class="grid" style="margin-top:25px">'+(shows.map(card).join("")||'<div class="card"><h2>No shows yet</h2><p>Create your first show to begin the release map.</p><a class="btn primary" href="create-podcast.html">CREATE SHOW</a></div>')+'</div><div class="card" style="margin-top:30px"><span class="eyebrow">READ-ONLY</span><p>The Release Map is calculated from existing show and episode records. It does not publish or modify content.</p></div></section>')}
