async function creatorStudioReleaseQueue(){const u=await user();if(!u){location.href="login.html";return}const creator=await creatorFor(u);if(!creator){shell('<section class="section wrap"><div class="form"><h2>CREATOR ACCESS</h2><p>Connect a creator profile to open the Release Queue.</p><a class="btn primary" href="create-podcast.html">BECOME A CREATOR</a></div></section>');return}const {data:pods}=await crSupabase.from("podcasts").select("id,title").eq("creator_id",creator.id).limit(100);const shows=pods||[],ids=shows.map(p=>p.id),names=Object.fromEntries(shows.map(p=>[p.id,p.title]));const {data:eps}=ids.length?await crSupabase.from("podcast_episodes").select("id,podcast_id,title,description,audio_url,duration_seconds,status,published_at,created_at").in("podcast_id",ids).order("created_at",{ascending:false}).limit(300):{data:[]};const episodes=eps||[];const complete=e=>!!e.title?.trim()&&!!e.description?.trim()&&!!e.audio_url?.trim()&&Number(e.duration_seconds||0)>0;const queue=episodes.filter(e=>complete(e)&&e.status!=="published"&&!e.published_at);const rows=queue.map((e,i)=>'<div class="card"><span class="eyebrow">QUEUE '+String(i+1).padStart(2,"0")+'</span><h2>'+esc(e.title||"Untitled episode")+'</h2><p><b>Show:</b> '+esc(names[e.podcast_id]||"Unknown show")+'</p><p>Core fields and audio are present. This episode is not yet published.</p><div class="actions"><a class="btn primary" href="creator-episode-review-board.html">REVIEW</a><a class="btn" href="creator-episode-workspace.html?id='+encodeURIComponent(e.id)+'">WORKSPACE</a></div></div>').join("");shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO · 5.73</span><h1>RELEASE <span class="glow">QUEUE</span></h1><p>A focused list of completed, unpublished episodes that can move through review.</p><div class="actions"><a class="btn primary" href="creator-episode-review-board.html">REVIEW BOARD</a><a class="btn" href="creator-studio-release-map.html">RELEASE MAP</a><a class="btn" href="creator-studio.html">STUDIO HOME</a></div></div><div class="card"><span class="eyebrow">QUEUE SIZE</span><h2>'+queue.length+'</h2><p>Completed episodes currently awaiting the next release workflow step.</p></div><div class="grid" style="margin-top:25px">'+(rows||'<div class="card"><h2>Queue is clear</h2><p>No completed unpublished episodes are currently detected.</p><a class="btn" href="creator-studio-priorities.html">VIEW PRIORITIES</a></div>')+'</div><div class="card" style="margin-top:30px"><span class="eyebrow">READ-ONLY</span><p>This queue only reads existing records. It does not publish, schedule, or change episode status.</p></div></section>')}
